c(1, "header lines 1-8", "positioning", "Avocation - Habit Tracker (App Store ID 1479581895; subtitle 'Daily planner & ADHD organizer') by David Joech (bundle app.avocation.avocation) — 369 written reviews, 43 storefronts, 21 Dec 2019 → 19 Aug 2026, mean 3.981, extracted 8 Sep 2026, analysed 12 Sep 2026; business model (review-derived): free download, hard free-tier cap of 3 habits (reported inconsistently), one-time 'lifetime' Pro unlock, no subscription, no ads; Pro prices in review text span $9.99–$15 / £9 / €9.99–17 / ¥68–98 / NT$490 / ฿399 / R$25; 44 reviewers (11.92%) state they paid; a beautiful product (coloured bubbles, a growing plant watered by habits, an avocado mascot, no streaks) with a monetisation wound", "free 3 habits; one-time lifetime Pro; no ads", "mixed", "369 reviews; 44 payers (11.92%)", "none", "corpus-level fact", "app-specific", [])
c(2, "§How to read this; §1.1–1.3, §1.5", "data-caveat", "Method: all 369 records read individually in full in original language (English, German 36, Simplified Chinese 24, Traditional Chinese 11, Spanish 17 + Latin America, Ukrainian and Russian 18, Portuguese 10, Italian 7, Turkish 7, Polish 4, Arabic 3, Thai 1, Vietnamese 4, French 1) in nine passes of ~40; 47 (12.74%) non-Latin script; 90 hand-curated themes, 1,079 assignments, mean 2.92 per review (max 11, 90 with exactly one), no regex or clustering; validated 0 unknown indices, 0 intra-theme duplicates, every theme with a family, 0 unassigned; reconciliation exact against 43 by_country files and manifest (5★ 173 / 4★ 101 / 3★ 41 / 2★ 23 / 1★ 31; mean 3.9810); 0 duplicate title+body pairs; 53 of 96 queried storefronts returned zero reviews (jp, hk, ie, ch among them — absence of written reviews, not of the app); census as of 8 Sep 2026; keyword sweep for price tokens and cap statements used as an audit of the hand map, not a classifier; every cited ID verified (§9.7); denominator 369 (one review = 0.27%); signal bands <0.1% ignore · 0.1–0.5% weak · 0.5–1% emerging · 1–3% meaningful · 3–5% very strong · >5% high-priority; HTML entities not decoded in source; known error risk at request vs complaint, paid_confirmed (a floor — ambiguous 'I highly recommend the paid version' excluded) and translation nuance", "n/a", "n/a", "369 (100%)", "none", "method statement", "app-specific", ["8175155082","6901836301","6231173329"])
c(3, "§Eight warnings 1; §1.6 #2", "data-caveat", "Only one storefront clears 50 reviews: US 119 (32.25%); next Germany 36, Great Britain 31, China 24, Ukraine 18, Spain 17, Canada 16 — exactly one standalone country claim (US); every other storefront limited evidence, percentages for shape only", "n/a", "n/a", "US 119 (32.25%)", "none", "corpus-level fact", "app-specific", [])
c(4, "§Eight warnings 2–3; §1.4 table (verbatim)", "timeline", "Volume and rating by year (verbatim): 2019 1 (5.000); 2020 60 (4.233); 2021 85 (3.847); 2022 104 (4.212); 2023 64 (3.766); 2024 30 (3.933); 2025 16 (3.625); 2026 to 19 Aug 9 (3.111); volume peaked in 2022 and fell ~91% by 2026 — ambiguous (declining installs, Apple's prompt behaviour, developer no longer prompting) and used as evidence for nothing; the product changed inside the span (free cap, price, maintenance status), so period percentages are preferred for trend claims; 2,433 days, 324 distinct review days; busiest month January 2022 (19); busiest day 4 (2021-01-23, 2022-01-21)", "n/a", "n/a", table("## 1.4 Date range and shape", 0), "none", "table", "app-specific", [])
